data.value:
SELECT Tab.EmployeeCode, Tab.EmployeeName,Tab.JobDesignationName,Tab.PayrollType, Tab.MonthYear, Tab.OverTimeHours, Tab.SalaryArrearDays FROM ( SELECT HRMS_SET_Employee.EmployeeCode, HRMS_SET_Employee.Fullname AS [EmployeeName], HRMS_JD.JobDesignationName, HRMS_PayrollType.Description AS PayrollType, UPPER(DATENAME(MONTH, FromDate) + ' ' + DATENAME(YEAR, FromDate)) AS MonthYear, ISNULL(HRMS_OverTime.OverTimeHours, 0) AS OverTimeHours, 0 AS SalaryArrearDays from HRMS_OverTime inner join HRMS_SET_Employee on HRMS_SET_Employee.PersonID = HRMS_OverTime.PersonID and HRMS_SET_Employee.CompanyID = HRMS_OverTime.CompanyID and HRMS_SET_Employee.Status =1 left join SET_Department on SET_Department.DepartmentID = HRMS_SET_Employee.FK_DepartmentID and SET_Department.Status =1 inner Join HRMS_PayrollType on HRMS_PayrollType.PayrollTypeID=HRMS_OverTime.PayrollTypeID AND HRMS_PayrollType.PayrollTypeCode=HRMS_OverTime.PayrollTypeCode AND HRMS_PayrollType.Status=1 left join SET_Section on SET_Section.SectionID = HRMS_SET_Employee.FK_SectionID LEFT JOIN SET_JobDesignation HRMS_JD ON HRMS_JD.JobDesignationID=[HRMS_SET_Employee].FK_JobDesignationID AND HRMS_JD.Status= 1 where HRMS_OverTime.Status = 1 And HRMS_OverTime.CompanyID = @CompanyID and HRMS_OverTime.PeriodID = @PeriodID And (HRMS_OverTime.FromDate >= @FromDate Or @FromDate is null) And (HRMS_OverTime.FromDate <= @ToDate Or @ToDate is null) {0}
UNION ALL
SELECT [HRMS_SET_Employee].EmployeeCode, [HRMS_SET_Employee].[FullName] AS [EmployeeName], HRMS_JD.JobDesignationName, [HRMS_PayrollType].[Description] AS [PayrollTypeName], UPPER(DATENAME(month, EMD.ForTheMonth) + ' ' + DATENAME(year, EMD.ForTheMonth)) AS MonthYear, 0 AS OverTimeHours, ISNULL(EMD.NoOfDays, 0) AS SalaryArrearDays FROM [HRMS_EmployeeMonthlyDeduction] EMD LEFT JOIN [HRMS_SET_Employee] ON [HRMS_SET_Employee].[PersonID] = EMD.[FromPersonID] AND [HRMS_SET_Employee].CompanyID = EMD.CompanyID INNER JOIN [HRMS_PayrollType] ON [HRMS_PayrollType].[PayrollTypeID]=EMD.[PayrollTypeID] Left Join SET_JobDesignation HRMS_JD ON HRMS_JD.JobDesignationID=[HRMS_SET_Employee].FK_JobDesignationID AND HRMS_JD.Status= 1 WHERE EMD.CompanyID = @CompanyID AND EMD.PeriodID = @PeriodID And (EMD.FromDate >= @FromDate Or @FromDate is null) And (EMD.FromDate <= @ToDate Or @ToDate is null) AND EMD.PayRollTypeCode = 1 AND EMD.Status = 1 AND Description = 'Salary Arrear' {0} ) Tab
